options(warn=1);suppressPackageStartupMessages({library(mice);library(survey)})
out<-neutro_normalize('work/mi_validation');csv<-function(x,n){p<-file.path(out,n);stopifnot(!neutro_file_exists(p));neutro_write_csv(x,p,row.names=FALSE)};save_new<-function(x,n){p<-file.path(out,n);stopifnot(!neutro_file_exists(p));neutro_saveRDS(x,p)}
neutro_cat('START',as.character(Sys.time()),'\n');print(sessionInfo());inputs<-c('work/analytic/analytic_v3.rds','work/cohort/C2_full_adult_design.rds');hash<-neutro_md5(inputs);d<-as.data.frame(neutro_readRDS(inputs[1]));ds<-neutro_readRDS(inputs[2]);for(v in c('Neutrophil','Lymphocyte','Platelet'))d[[paste0('log_',v)]]<-log(d[[paste0(v,'_count')]])
edbefore<-sum(is.na(d$education));mask<-d$DMDEDUC2%in%c(7,9);d$education[mask]<-NA;csv(data.frame(N=nrow(d),DMDEDUC2_7=sum(d$DMDEDUC2%in%7),DMDEDUC2_9=sum(d$DMDEDUC2%in%9),education_missing_before=edbefore,education_missing_after=sum(is.na(d$education)),newly_set_NA=sum(mask&!is.na(neutro_readRDS(inputs[1])$education))),'education_missing_audit.csv')
vars<-c('depression','log_Neutrophil','log_Lymphocyte','log_Platelet','age','sex','bmi','smoking','race_eth','antidep','education','pir','alcohol4','diabetes','hypertension','log10_cotinine','any_nsaid','any_corticosteroid','any_statin','SDDSRVYR','SDMVSTRA','SDMVPSU');a<-d[,vars];a$log_weight<-log(d$WTMEC_adj);a$education<-factor(a$education,levels=c('Less than high school','High school/GED','Some college','College or above'))
for(v in c('race_eth','education','diabetes','hypertension','SDDSRVYR','SDMVSTRA','SDMVPSU'))a[[v]]<-factor(a[[v]])
a_original<-a; numeric_vars<-names(a)[vapply(a,is.numeric,logical(1))];centers<-sapply(a[numeric_vars],mean,na.rm=TRUE);scales<-sapply(a[numeric_vars],sd,na.rm=TRUE);stopifnot(all(scales>0));for(v in numeric_vars)a[[v]]<-(a[[v]]-centers[v])/scales[v];csv(data.frame(variable=numeric_vars,center=centers,scale=scales),'imputation_scaling.csv');method<-setNames(rep('',ncol(a)),names(a));method[c('education','alcohol4')]<-'polyreg';method[c('diabetes','hypertension')]<-'logreg';method[c('pir','log10_cotinine')]<-'pmm';csv(data.frame(variable=names(a),method=method,missing=sapply(a,function(x)sum(is.na(x)))),'methods.csv');csv(data.frame(m=20,maxit=20,seed=20261008,donors=5),'settings.csv')

imp<-neutro_readRDS('work/imputation/imputations_standardized.rds');
inverse_data<-function(filled){for(v in intersect(numeric_vars,names(filled)))filled[[v]]<-filled[[v]]*scales[v]+centers[v];if(is.numeric(filled$education))filled$education<-factor(levels(a_original$education)[as.integer(filled$education)],levels=levels(a_original$education))else filled$education<-factor(as.character(filled$education),levels=levels(a_original$education));filled}
# Full C2 survey base; subset only after joining imputed values by SEQN.
base<-ds$variables;ix<-match(base$SEQN,d$SEQN);base$included<-!is.na(ix);for(v in c('race_eth','sex','smoking','alcohol4','log10_cotinine','education','pir','diabetes','hypertension','any_nsaid','any_corticosteroid','any_statin'))base[[v]]<-d[[v]][ix];base$cycle_factor<-factor(base$SDDSRVYR);base$PHQ15<-as.numeric(base$PHQ9_total>=15);ds$variables<-base;fulldes<-subset(ds,included);SDfixed<-0.381754443;csv(data.frame(N=33174,weighted_log_SD=SDfixed),'fixed_SD.csv')
extras<-c(Model1='',Model2='+ log10_cotinine + alcohol4 + education + pir',Model3='+ log10_cotinine + alcohol4 + education + pir + diabetes + hypertension + any_nsaid + any_corticosteroid + any_statin');cells<-c('log_Neutrophil','log_Lymphocyte','log_Platelet');outcomes<-c(main='depression',total='PHQ9_total',severe='PHQ15');registry<-records<-data.frame()
record_fit<-function(des,id,outcome,imputation,extra){f<-as.formula(paste(outcome,'~ log_Neutrophil + log_Lymphocyte + log_Platelet + age + sex + bmi + smoking + cycle_factor + race_eth',extra));ww<-character();neutro_cat('MODEL_START',id,outcome,'imputation',imputation,'N',nrow(des$variables),'\n');print(f);m<-withCallingHandlers(svyglm(f,design=des,family=if(outcome=='PHQ9_total')quasipoisson(link='log')else quasibinomial()),warning=function(w){ww<<-c(ww,conditionMessage(w));neutro_cat('MODEL_WARNING',conditionMessage(w),'\n');invokeRestart('muffleWarning')});print(summary(m));registry<<-rbind(registry,data.frame(model=id,outcome=outcome,imputation=imputation,N=nobs(m),formula=paste(deparse(f),collapse=' '),converged=m$converged,design_df=degf(des),residual_df=m$df.residual,warning_count=length(ww),warnings=paste(ww,collapse=' | ')))
 terms<-if(outcome=='depression')cells else cells[1];for(v in terms)records<<-rbind(records,data.frame(model=id,outcome=outcome,imputation=imputation,type='coefficient',term=v,Q=unname(coef(m)[v]),U=unname(vcov(m)[v,v]),dfcom=m$df.residual,N=nobs(m)))
 if(outcome=='depression')for(j in 2:3){vec<-setNames(rep(0,length(coef(m))),names(coef(m)));vec[cells[1]]<-1;vec[cells[j]]<--1;c<-svycontrast(m,vec);records<<-rbind(records,data.frame(model=id,outcome=outcome,imputation=imputation,type='contrast',term=paste(cells[1],cells[j],sep=' - '),Q=as.numeric(coef(c)),U=as.numeric(SE(c))^2,dfcom=degf(des),N=nobs(m)))};neutro_cat('MODEL_END\n');if(length(ww)||!isTRUE(m$converged))stop('Analysis model warning/nonconvergence; see log; no settings changed')}
for(i in 1:20){filled<-inverse_data(complete(imp,i));bb<-base;for(v in names(method)[method!=''])bb[[v]]<-filled[[v]][ix];design<-ds;design$variables<-bb;domain<-subset(design,included);for(id in names(extras))for(o in outcomes)record_fit(domain,id,o,i,extras[id])}
ccvars<-c('alcohol4','education','pir','diabetes','hypertension','log10_cotinine','any_nsaid','any_corticosteroid','any_statin');ds$variables$cc<-base$included&complete.cases(base[,ccvars]);cc<-subset(ds,cc);stopifnot(nrow(cc$variables)==29360);for(id in names(extras))for(o in outcomes)record_fit(cc,id,o,0,extras[id]);csv(registry,'model_registry.csv');csv(records,'model_estimates_variances.csv')
# Coefficient complete-data df is model residual; contrast complete-data df = degf(design).
res<-data.frame();keys<-unique(records[records$imputation>0,c('model','outcome','type','term')]);for(k in seq_len(nrow(keys))){key<-keys[k,];rr<-records[records$model==key$model&records$outcome==key$outcome&records$type==key$type&records$term==key$term&records$imputation>0,];dfcom<-min(rr$dfcom);p<-pool.scalar(rr$Q,rr$U,n=dfcom+1,k=1);se<-sqrt(p$t);crit<-qt(.975,p$df);ccr<-records[records$model==key$model&records$outcome==key$outcome&records$term==key$term&records$imputation==0,];ccse<-sqrt(ccr$U);cccrit<-qt(.975,ccr$dfcom);iscon<-key$type=='contrast';res<-rbind(res,data.frame(key,N_MI=33174,N_CC=ccr$N,beta_MI=p$qbar,SE_MI=se,effect_MI=if(iscon)NA else exp(p$qbar),lower_MI=if(iscon)p$qbar-crit*se else exp(p$qbar-crit*se),upper_MI=if(iscon)p$qbar+crit*se else exp(p$qbar+crit*se),P_MI=2*pt(-abs(p$qbar/se),p$df),df_MI=p$df,dfcom=dfcom,FMI=p$fmi,RVI=p$r,lambda=(1+1/20)*p$b/p$t,beta_CC=ccr$Q,effect_CC=if(iscon)NA else exp(ccr$Q),lower_CC=if(iscon)ccr$Q-cccrit*ccse else exp(ccr$Q-cccrit*ccse),upper_CC=if(iscon)ccr$Q+cccrit*ccse else exp(ccr$Q+cccrit*ccse),P_CC=2*pt(-abs(ccr$Q/ccse),ccr$dfcom),SD_OR_MI=if(key$term==cells[1])exp(p$qbar*SDfixed)else NA,SD_lower_MI=if(key$term==cells[1])exp((p$qbar-crit*se)*SDfixed)else NA,SD_upper_MI=if(key$term==cells[1])exp((p$qbar+crit*se)*SDfixed)else NA,SD_OR_CC=if(key$term==cells[1])exp(ccr$Q*SDfixed)else NA,SD_lower_CC=if(key$term==cells[1])exp((ccr$Q-cccrit*ccse)*SDfixed)else NA,SD_upper_CC=if(key$term==cells[1])exp((ccr$Q+cccrit*ccse)*SDfixed)else NA))};csv(res,'Rubin_MI_CC_comparison.csv')
